import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"文档数据库","description":"","frontmatter":{"title":"文档数据库","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/document-db.md","filePath":"cs/document-db.md","lastUpdated":1789023840000}'),h={name:"cs/document-db.md"};function _(m,a,E,u,B,A){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="文档数据库" tabindex="-1">文档数据库 <a class="header-anchor" href="#文档数据库" aria-label="Permalink to &quot;文档数据库&quot;">​</a></h1><div class="epigraph"><p>文档是嵌套的自描述记录，默认一次读整图。二级索引与聚合管道补查询；跨文档事务曾是弱项，现正在往回补 SQL 课已有的东西。</p><footer>—— 据 Stonebraker 对文档；MongoDB 文档模型实践；阻抗失配对照</footer></div><p><a href="/cs/rocksdb">上一课</a>给了 KV LSM。本课把值变成 JSON/BSON 一类文档。缺口是数据模型：1NF 分解 vs 嵌套预连接。ORM 阻抗课的对象图在这里接近存储形状。不是「无 schema」——有 schema 演化与稀疏字段，约束弱于关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>嵌套数组：订单内行项目一次读出，免连接。更新一行项目可能重写整文档或用路径更新。缺口是<strong>粒度</strong>：文档太大则回表式读放大，太碎则又变关系。二级索引：对嵌套路径建 B+ 或 LSM 索引，写放大按路径。聚合：管道像受限的物理计划，优化器弱于 Selinger 全搜索。</p><p>事务：早期单文档原子；多文档事务回到 2PL/MVCC 故事。分片键常是文档 id 或租户。</p><p><span class="marginnote">文档库不是向量库、不是图库。查询语言不是 SQL 全集。本课模型，不背某查询语法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建模：按读路径嵌套，按写冲突切文档。索引只盖过滤路径。与 CDC：oplog 是逻辑日志。与 Parquet：分析常倒出列文件，HTAP 新鲜度问题再现。</p><p>NULL 与缺字段：稀疏，与三值不同，查询要定义缺省。</p>',10)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E5%B5%8C%E5%A5%97%E6%96%87%E6%A1%A3%22%5D%20--%3E%20GET%5B%22%E6%8C%89%20id%20%E4%B8%80%E6%AC%A1%E8%AF%BB%22%5D%0A%20%20DOC%20--%3E%20IDX%5B%22%E8%B7%AF%E5%BE%84%E4%BA%8C%E7%BA%A7%E7%B4%A2%E5%BC%95%22%5D%0A%20%20IDX%20--%3E%20FILT%5B%22%E8%BF%87%E6%BB%A4%E5%90%8E%E5%86%8D%E5%8F%96%E6%96%87%E6%A1%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>存储常 LSM（WiredTiger、RocksDB）。覆盖：投影可只返回字段，延迟物化在文档内。计划回归：忘了索引变成全集合扫。</p><p>关系对照：连接存在但贵，鼓励反规范化——5NF 课的显式冗余，缺维护合同则漂移。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Bigtable 宽列。也不把文档当全文引擎——全文另倒排。图多跳文档嵌套表达差。</p><p>后课默认：读路径聚合用文档；多对多连接用关系或图。宽列 Bigtable：稀疏列族、行键设计，不是 JSON 树。</p><p>文档是预物化的外模式，内模式仍是页或 SST。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文档嵌套服务一次读出；索引与多文档事务补关系能力。</li><li>过大过碎都失败；分析常外倒列存。</li><li>宽列 Bigtable 下一课。</li><li>出处：Stonebraker；文档库实践；阻抗课。</li></ul>',9))])}const f=i(h,[["render",_]]);export{S as __pageData,f as default};
